function isAnagram(s, t) {
  // Return true if t is a rearrangement of s

}

challenges.solution:
function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const counts = {};
  for (const c of s) counts[c] = (counts[c] || 0) + 1;
  for (const c of t) {
    if (!counts[c]) return false;
    counts[c]--;
  }
  return true;
}

