function isValid(s) {
  // Return true if the brackets are balanced and correctly nested

}

challenges.solution:
function isValid(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const c of s) {
    if (c === '(' || c === '[' || c === '{') {
      stack.push(c);
    } else {
      if (stack.pop() !== pairs[c]) return false;
    }
  }
  return stack.length === 0;
}

challenges.starterCode:
function maxProfit(prices) {
  // Return the best profit from one buy and one later sell

}

challenges.solution:
function maxProfit(prices) {
  let cheapest = Infinity;
  let best = 0;
  for (const price of prices) {
    if (price < cheapest) cheapest = price;
    else if (price - cheapest > best) best = price - cheapest;
  }
  return best;
}
